<?php
require_once __DIR__ . '/phase2.php'; p2_start();$pdo=p2_db();p2_check_csrf();
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['complete'])){$id=(int)$_POST['complete'];$stmt=$pdo->prepare('SELECT matter_id,title FROM p2_deadlines WHERE id=?');$stmt->execute([$id]);$item=$stmt->fetch();if($item){$pdo->prepare("UPDATE p2_deadlines SET status='complete' WHERE id=?")->execute([$id]);p2_log('deadline.completed',"Completed deadline: {$item['title']}",$item['matter_id']);}p2_redirect('deadlines.php','Deadline marked complete.');}
$items=$pdo->query("SELECT d.*,m.reference,m.title matter_title FROM p2_deadlines d LEFT JOIN p2_matters m ON m.id=d.matter_id WHERE d.status='open' ORDER BY d.due_on")->fetchAll();
p2_page('Deadline watch','deadlines.php',function()use($items){?><div class="toolbar"><div><h1>Deadline watch</h1><p class="subhead">Open obligations sorted by due date with live day-count badges.</p></div><a class="button" href="matters.php">Add from a matter</a></div><section class="card"><?php if(!$items):?><div class="empty">No open deadlines.</div><?php else:?><table><thead><tr><th>Deadline</th><th>Matter</th><th>Priority</th><th>Due date</th><th></th></tr></thead><tbody><?php foreach($items as $item):$timing=p2_deadline_timing($item['due_on']);?><tr><td><?=p2_h($item['title'])?></td><td><a href="matters.php?id=<?=$item['matter_id']?>"><?=p2_h($item['reference']?:$item['matter_title']?:'General')?></a></td><td><?=p2_status_badge($item['priority'])?></td><td class="<?=p2_h($timing['class'])?>"><?=p2_h($item['due_on'])?><br><?=p2_due_badge($item['due_on'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=p2_csrf()?>"><button class="button secondary" name="complete" value="<?=$item['id']?>">Complete</button></form></td></tr><?php endforeach;?></tbody></table><?php endif;?></section><?php }); ?>
